#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string s;cin>>s;string r;
for(size_t i=0;i<s.size();){
if(s[i]=='G'){r+='G';++i;}
else if(s[i]=='('&&i+1<s.size()&&s[i+1]==')'){r+='o';i+=2;}
else{r+="al";i+=4;}}
printf("%s\n",r.c_str());return 0;}

